# --- VLC embalado (build portátil) -----------------------------------------
# Para o .exe correr em qualquer PC SEM o VLC instalado, o build pode incluir
# uma pasta "vlc/" (com libvlc.dll, libvlccore.dll e a subpasta plugins/) ao
# lado do executável. Se essa pasta existir, apontamos o python-vlc para ela
# ANTES do import; caso contrário mantém-se o comportamento clássico (usa o
# VLC instalado no sistema). No macOS o equivalente é libvlc.dylib + plugins.
def _setup_bundled_vlc():
    try:
        if getattr(sys, "frozen", False):
            # PyInstaller 6 coloca os datas em _internal/ (= sys._MEIPASS);
            # versões antigas colocavam ao lado do exe. Verifica ambos.
            bases = [os.path.dirname(sys.executable)]
            _mei = getattr(sys, "_MEIPASS", None)
            if _mei:
                bases.append(_mei)
        else:
            bases = [os.path.dirname(os.path.abspath(__file__))]
        libname = ("libvlc.dll" if sys.platform == "win32"
                   else "libvlc.dylib" if sys.platform == "darwin"
                   else "libvlc.so")
        vlc_dir = None
        libpath = None
        for _b in bases:
            _cand = os.path.join(_b, "vlc")
            if os.path.isfile(os.path.join(_cand, libname)):
                vlc_dir = _cand
                libpath = os.path.join(_cand, libname)
                break
        if not vlc_dir:
            return  # sem pasta vlc/ embalada → usa o VLC do sistema
        # python-vlc respeita estas variáveis se definidas antes do import:
        os.environ.setdefault("PYTHON_VLC_LIB_PATH", libpath)
        plugins = os.path.join(vlc_dir, "plugins")
        if os.path.isdir(plugins):
            os.environ.setdefault("VLC_PLUGIN_PATH", plugins)
        # Windows: o libvlc.dll precisa de encontrar o libvlccore.dll
        if hasattr(os, "add_dll_directory"):
            os.add_dll_directory(vlc_dir)
        if not _IS_WORKER_PROCESS:
            print(f"[VLC] A usar VLC embalado em: {vlc_dir}")
    except Exception as _e_vlcdir:
        print(f"[VLC] Setup do VLC embalado ignorado: {_e_vlcdir}")


_setup_bundled_vlc()

