def get_vlc_args():
    base_args = ["--no-video", "--verbose=-1", "--audio-time-stretch"]
    if sys.platform.startswith("win"):
        base_args.append("--aout=directsound")
    elif sys.platform == "darwin":
        base_args.append("--aout=coreaudio")
    else:
        base_args.append("--aout=pulse")
    return base_args


def _get_traktor_history_dir():
    import glob as _glob
    home = os.path.expanduser("~")
    found = []
    for b in (os.path.join(home, "Documents", "Native Instruments"),
              os.path.join(home, "Native Instruments")):
        if os.path.isdir(b):
            for d in _glob.glob(os.path.join(b, "Traktor*")):
                h = os.path.join(d, "History")
                if os.path.isdir(h):
                    found.append(h)
    if found:
        return max(found, key=os.path.getmtime)
    return None


