def _parse_serato_session(filepath):
    """Best-effort: extrai caminhos de audio de uma .session (Serato classico)."""
    import struct
    AUDIO = ('.mp3', '.wav', '.flac', '.aiff', '.aif', '.ogg', '.m4a', '.aac', '.alac', '.wma')
    out = []
    try:
        with open(filepath, 'rb') as fh:
            data = fh.read()
    except Exception:
        return out
    i, n = 0, len(data)
    while i + 8 <= n:
        try:
            length = struct.unpack('>I', data[i + 4:i + 8])[0]
        except Exception:
            break
        if data[i:i + 4] == b'oent':
            body = data[i + 8:i + 8 + length]
            j, m = 0, len(body)
            while j + 8 <= m:
                try:
                    l2 = struct.unpack('>I', body[j + 4:j + 8])[0]
                except Exception:
                    break
                if body[j:j + 4] == b'adat':
                    b2 = body[j + 8:j + 8 + l2]
                    k, mm = 0, len(b2)
                    while k + 8 <= mm:
                        try:
                            flen = struct.unpack('>I', b2[k + 4:k + 8])[0]
                        except Exception:
                            break
                        try:
                            s = b2[k + 8:k + 8 + flen].decode('utf-16-be').rstrip('\x00')
                        except Exception:
                            s = ''
                        if s and s.lower().endswith(AUDIO):
                            out.append(s)
                        k += 8 + flen
                j += 8 + l2
        i += 8 + length
    return out


def _get_serato_sqlite_path():
    home = os.path.expanduser("~")
    for c in (os.path.join(home, "Music", "_Serato_", "master.sqlite"),
              os.path.join(home, "Music", "_Serato_", "database", "master.sqlite"),
              os.path.join(home, "Documents", "_Serato_", "master.sqlite")):
        if os.path.isfile(c):
            return c
    for root in (os.path.join(home, "Music", "_Serato_"), os.path.join(home, "Documents", "_Serato_")):
        if os.path.isdir(root):
            for dp, _dn, fn in os.walk(root):
                for f in fn:
                    if f.lower() == "master.sqlite":
                        return os.path.join(dp, f)
    return None


def _serato_sqlite_latest_track(db_path):
    """Serato 4.x: le master.sqlite via copia temporaria (evita 'database locked').
    Introspecao best-effort da tabela/coluna de caminho mais recente."""
    if not db_path or not os.path.isfile(db_path):
        return None
    import sqlite3, tempfile, shutil
    tmp = None
    try:
        fd, tmp = tempfile.mkstemp(suffix=".sqlite"); os.close(fd)
        shutil.copy2(db_path, tmp)
        con = sqlite3.connect(tmp); con.row_factory = sqlite3.Row
        cur = con.cursor()
        cur.execute("SELECT name FROM sqlite_master WHERE type='table'")
        tables = [r[0] for r in cur.fetchall()]
        best = None
        for tbl in tables:
            try:
                cur.execute("PRAGMA table_info(%s)" % tbl)
                cols = [c[1] for c in cur.fetchall()]
            except Exception:
                continue
            path_col = next((c for c in cols if c.lower() in ("filepath", "path", "location", "file", "fullpath", "uri")), None)
            if not path_col:
                path_col = next((c for c in cols if ("path" in c.lower() or "file" in c.lower() or "location" in c.lower())), None)
            if not path_col:
                continue
            time_col = next((c for c in cols if c.lower() in ("playtime", "played_at", "timestamp", "time", "date", "starttime", "lastplayed")), "rowid")
            try:
                cur.execute("SELECT %s AS p FROM %s ORDER BY %s DESC LIMIT 30" % (path_col, tbl, time_col))
            except Exception:
                continue
            for r in cur.fetchall():
                p = r["p"]
                if not p:
                    continue
                p = str(p)
                if p.startswith("file://"):
                    from urllib.parse import unquote, urlparse
                    p = unquote(urlparse(p).path)
                    if os.name == "nt" and p.startswith("/"):
                        p = p[1:]
                npth = os.path.normpath(p)
                if os.path.isfile(npth):
                    best = npth
                    break
            if best:
                break
        con.close()
        return best
    except Exception as e:
        print(f"[Co-Pilot] Serato sqlite: {e}")
        return None
    finally:
        if tmp and os.path.isfile(tmp):
            try:
                os.remove(tmp)
            except Exception:
                pass


def _get_vdj_history_path():
    """Pasta onde o VirtualDJ escreve o histórico.

    O caminho fixo ~/Documents/VirtualDJ/History falha em três casos comuns:
    Documentos redirecionados para o OneDrive, sistema em português
    ("Documentos") e instalações que escrevem em LOCALAPPDATA. Quando há
    mais do que um candidato válido, ganha aquele com o .m3u mais recente —
    é onde o VirtualDJ está mesmo a registar AGORA.
    """
    home = os.path.expanduser("~")
    if sys.platform == "darwin":
        cands = [os.path.join(home, "Music", "VirtualDJ", "History"),
                 os.path.join(home, "Documents", "VirtualDJ", "History")]
    else:
        cands = [os.path.join(home, "Documents", "VirtualDJ", "History")]
        od = os.environ.get("OneDrive", "")
        if od:
            cands += [os.path.join(od, "Documents", "VirtualDJ", "History"),
                      os.path.join(od, "Documentos", "VirtualDJ", "History")]
        la = os.environ.get("LOCALAPPDATA", "")
        if la:
            cands.append(os.path.join(la, "VirtualDJ", "History"))
        cands.append(os.path.join(home, "Music", "VirtualDJ", "History"))
    existing = [c for c in cands if os.path.isdir(c)]
    if not existing:
        return cands[0]

    def _newest_m3u(d):
        best = 0.0
        try:
            for fn in os.listdir(d):
                if fn.lower().endswith(".m3u"):
                    try:
                        best = max(best, os.path.getmtime(os.path.join(d, fn)))
                    except OSError:
                        pass
        except OSError:
            pass
        return best

    existing.sort(key=_newest_m3u, reverse=True)
    return existing[0]


def _get_rekordbox_db_path():
    """Descobre o path da master.db do Rekordbox (v6 ou v7).

    Estratégia: a Pioneer mudou o nome da pasta entre versões:
      - Rekordbox 6: .../Pioneer/rekordbox6/master.db
      - Rekordbox 7: .../Pioneer/rekordbox/master.db
    Em vez de codificar nomes, percorremos todas as sub-pastas de Pioneer/
    e devolvemos a primeira que tiver uma master.db. Isto também apanha
    futuras mudanças de nome (rekordbox8, etc.) sem termos de actualizar.

    Se nenhuma for encontrada, devolve o path mais provável para que o
    diálogo de erro diga ao utilizador onde o MixAi procurou.
    """
    # 1. Descobrir a pasta-pai "Pioneer"
    if sys.platform.startswith("win"):
        appdata = os.environ.get("APPDATA") or os.path.expanduser(r"~\AppData\Roaming")
        pioneer_root = os.path.join(appdata, "Pioneer")
    elif sys.platform == "darwin":
        pioneer_root = os.path.expanduser("~/Library/Pioneer")
    else:
        pioneer_root = os.path.expanduser("~/.Pioneer")

    # 2. Varrer sub-pastas à procura de master.db
    # Preferência: qualquer sub-pasta chamada "rekordbox" (sem sufixo, v7)
    # vem primeiro. Ordenação alfabética reversa coloca "rekordbox" antes
    # de "rekordbox6".
    found = []
    if os.path.isdir(pioneer_root):
        try:
            for entry in sorted(os.listdir(pioneer_root)):
                subdir = os.path.join(pioneer_root, entry)
                if not os.path.isdir(subdir):
                    continue
                # Só nos interessam pastas que comecem por "rekordbox"
                if not entry.lower().startswith("rekordbox"):
                    continue
                candidate = os.path.join(subdir, "master.db")
                if os.path.isfile(candidate):
                    found.append((entry.lower(), candidate))
        except OSError:
            pass

    if found:
        # Ordenar por nome da pasta: "rekordbox" (v7) < "rekordbox6" (v6)
        # alfabeticamente — por isso a mais recente aparece primeiro.
        found.sort(key=lambda t: t[0])
        return found[0][1]

    # 3. Fallback: o path mais provável para a mensagem de erro fazer sentido
    return os.path.join(pioneer_root, "rekordbox", "master.db")


def _build_rekordbox_location_url(normalized_path):
    unix_path = normalized_path.replace(os.sep, '/')
    if sys.platform.startswith("win"):
        return f"file://localhost/{unix_path}"
    return f"file://localhost{unix_path}" if unix_path.startswith('/') else f"file://localhost/{unix_path}"


def _build_traktor_key_path(music_path_nml):
    absolute_path = os.path.abspath(music_path_nml)
    if sys.platform.startswith("win"):
        drive, tail = os.path.splitdrive(absolute_path)
        if drive:
            return f"{drive.replace(':', '').upper()}:/{tail.replace(os.sep, '/')}"
        return absolute_path.replace(os.sep, '/')
    unix_path = absolute_path.replace(os.sep, '/')
    return unix_path if unix_path.startswith('/') else f"/{unix_path}"


