# =====================================================================
# Robustez / Estabilidade V4 — helpers
# =====================================================================
# - _auto_backup_db: cria cópia da DB antes de operações destrutivas,
#   mantém os últimos N (default 3).
# - DBMaintenanceThread: corre VACUUM + PRAGMA integrity_check em background,
#   30 s depois do arranque. Não bloqueia o utilizador.
# - _safe_qthread_run: decorador para envolver QThread.run() — captura
#   excepções, faz log, sinaliza um failure signal se existir, em vez
#   de crashar o processo.
# =====================================================================

import shutil as _shutil_v4
from datetime import datetime as _dt_v4


def _auto_backup_db(max_backups=3, reason="auto"):
    """Cria uma cópia timestamped da DB. Mantém últimos N backups.
    Devolve o path do backup criado, ou None se algo falhar."""
    try:
        if not os.path.exists(DB_SQLITE):
            return None
        backup_dir = os.path.join(os.path.dirname(DB_SQLITE) or ".", "backups")
        os.makedirs(backup_dir, exist_ok=True)
        ts = _dt_v4.now().strftime("%Y%m%d_%H%M%S")
        dst = os.path.join(backup_dir, f"music_database_{reason}_{ts}.db")
        # CORREÇÃO (integridade): a BD corre em WAL — as transações mais
        # recentes podem estar em music_database.db-wal e ainda não no .db
        # principal. Um shutil.copy2 do .db sozinho gerava backups SEM as
        # últimas escritas (e potencialmente inconsistentes se uma escrita
        # estivesse a meio). A API Connection.backup() do sqlite3 produz um
        # snapshot consistente que inclui o conteúdo do WAL.
        try:
            src_conn = sqlite3.connect(DB_SQLITE, timeout=5.0)
            try:
                dst_conn = sqlite3.connect(dst)
                try:
                    src_conn.backup(dst_conn)
                finally:
                    dst_conn.close()
            finally:
                src_conn.close()
        except Exception as e_bk:
            # Fallback best-effort para a cópia simples (melhor que nada)
            print(f"[Backup] sqlite backup API falhou ({e_bk}); a usar copy2")
            _shutil_v4.copy2(DB_SQLITE, dst)
        # Rotação: manter só os últimos max_backups por reason
        try:
            prefix = f"music_database_{reason}_"
            existing = sorted(
                [f for f in os.listdir(backup_dir)
                 if f.startswith(prefix) and f.endswith(".db")],
                reverse=True,
            )
            for old in existing[max_backups:]:
                try:
                    os.remove(os.path.join(backup_dir, old))
                except Exception:
                    pass
        except Exception as _e_rot:
            print(f"[BackupRotation] aviso: {_e_rot}")
        print(f"[Backup] DB salvaguardada em {dst}")
        return dst
    except Exception as e:
        print(f"[Backup] Falhou: {e}")
        return None


def _safe_qthread_run(run_method):
    """Decorador para QThread.run — apanha excepções, faz log e tenta
    emitir um sinal de falha se a thread tiver um attr 'failed' ou
    'set_failed'. Evita crashes silenciosos do processo."""
    def wrapper(self, *args, **kwargs):
        try:
            return run_method(self, *args, **kwargs)
        except Exception as _e_run:
            import traceback
            tb = traceback.format_exc()
            print(f"[Thread/{type(self).__name__}] excepção não tratada: {_e_run}\n{tb}")
            for sig_name in ("failed", "set_failed", "error", "analysis_error"):
                sig = getattr(self, sig_name, None)
                if sig is not None and hasattr(sig, "emit"):
                    try:
                        sig.emit(str(_e_run))
                        break
                    except Exception:
                        pass
    return wrapper

