# --- Optional structured Track representation ------------------------------
# The internal database format is still dict-based (path -> info dict) for
# backward compatibility with the whole codebase. This dataclass is an
# optional typed view for new code that prefers attribute access.
# Use Track.from_dict(info) / track.to_dict() to convert.
@dataclass
class Track:
    path: str = ""
    bpm: float = 120.0
    camelot: str = "N/A"
    genre: str = "Unknown"
    energy: float = 0.5
    loudness: float = -9.0
    centroid: float = 0.0
    cluster: int = 0
    duration: float = 0.0
    onset_density: float = 0.0
    rhythm_variance: float = 0.0
    intro_energy: float = 0.5
    intro_onset_density: float = 0.0
    intro_rhythm_variance: float = 0.0
    outro_energy: float = 0.5
    outro_onset_density: float = 0.0
    outro_rhythm_variance: float = 0.0
    intro_loudness: float = -9.0
    outro_loudness: float = -9.0
    intro_perceptual_loudness_slew_rate: float = 0.0
    intro_spectral_flatness: float = 0.0
    outro_perceptual_loudness_slew_rate: float = 0.0
    outro_spectral_flatness: float = 0.0
    intro_rhythm_pattern: List = field(default_factory=list)
    outro_rhythm_pattern: List = field(default_factory=list)
    groove_pattern: List = field(default_factory=list)
    # 48 números (3 bandas x 16 posições no compasso) do `mixai_groove`.
    # Sem isto, o `from_dict` deitava o campo fora — filtra por
    # `__dataclass_fields__` e ignora as chaves que não conhece.
    groove_bar: List = field(default_factory=list)
    groove_bar_v: int = 0
    intro_groove_pattern: List = field(default_factory=list)
    outro_groove_pattern: List = field(default_factory=list)
    pulse_clarity: float = 0.0
    intro_pulse_clarity: float = 0.0
    outro_pulse_clarity: float = 0.0
    sections: List = field(default_factory=list)
    hot_cues: List = field(default_factory=list)
    hash: Optional[str] = None
    analysis: Optional[str] = None
    _fast_key: Optional[List] = None

    @classmethod
    def from_dict(cls, info: dict, path: str = "") -> "Track":
        """Build a Track from a music_data entry dict. Ignores unknown keys."""
        allowed = {f for f in cls.__dataclass_fields__.keys()}
        kwargs = {k: v for k, v in info.items() if k in allowed}
        if path and "path" not in kwargs:
            kwargs["path"] = path
        return cls(**kwargs)

    def to_dict(self) -> dict:
        """Inverse of from_dict. Excludes the path field (used as dict key)."""
        d = {k: getattr(self, k) for k in self.__dataclass_fields__.keys()
             if k != "path"}
        return d


def check_write_permissions():
    test_file = os.path.join(DB_FOLDER_NAME, "test_write.tmp")
    if os.path.exists(test_file):
        try:
            os.remove(test_file)
        except Exception:
            pass

    for attempt in range(2):
        try:
            with open(test_file, 'w') as f:
                f.write("test")
            os.remove(test_file)
            return True
        except Exception as e:
            if attempt == 0:
                time.sleep(0.5)
                continue
            print(f"Permission check failed in '{DB_FOLDER_NAME}': {e}")
            print("Is another instance of MixAi DJ Copilot running?")
            return False
    return False


