def is_frozen():
    return getattr(sys, 'frozen', False)


def setup_logging():
    # RotatingFileHandler: o mixai.log deixa de crescer sem limite (2 MB × 3
    # cópias) — essencial para diagnóstico no terreno sem encher o disco.
    # encoding="utf-8": sem isto o Windows abre o ficheiro em cp1252 e
    # qualquer acento numa mensagem de log rebenta com UnicodeEncodeError.
    from logging.handlers import RotatingFileHandler
    try:
        fh = RotatingFileHandler(LOG_FILE, maxBytes=2_000_000,
                                 backupCount=3, encoding="utf-8")
    except Exception:
        fh = logging.FileHandler(LOG_FILE, encoding="utf-8")
    logging.basicConfig(
        level=logging.INFO,
        format='%(asctime)s - %(name)s - %(levelname)s - %(message)s',
        handlers=[
            fh,
            logging.StreamHandler()
        ]
    )
    return logging.getLogger(__name__)


logger = setup_logging()


