# ----------------------------------------------------------------------
# MAPA DE GÉNEROS — Compatibilidade e Aliases
# GENRE_COMPATIBILITY, GENRE_ALIASES → mixai_core
# Usado tanto na pesquisa como na geração de playlists.
# ----------------------------------------------------------------------

# Conjunto com todos os nomes de género conhecidos (para detecção automática na pesquisa)
_ALL_KNOWN_GENRES = set(GENRE_COMPATIBILITY.keys()) | set(GENRE_ALIASES.keys()) | set(GENRE_ALIASES.values())


@lru_cache(maxsize=1024)
def normalize_genre(genre_str):
    """Normaliza um género: lowercase, trim, resolve aliases/typos."""
    g = genre_str.lower().strip()
    if g in GENRE_ALIASES:
        return GENRE_ALIASES[g]
    return g


@lru_cache(maxsize=1024)
def split_genres(genre_str):
    """
    Separa géneros compostos em partes individuais normalizadas.
    Ex: "House/Pop" → ('house', 'pop')
        "Afro House" → ('afro house',)

    Retorna uma tuple (imutável) para ser seguro com @lru_cache.
    Callers que queiram uma list devem fazer list(split_genres(...)).
    """
    g = genre_str.strip()
    if not g:
        return ('unknown',)
    parts = re.split(r'[/,;|&]+', g)
    normalized = []
    for part in parts:
        part = part.strip()
        if not part:
            continue
        p_norm = normalize_genre(part)
        if p_norm:
            normalized.append(p_norm)
    return tuple(normalized) if normalized else (g.lower().strip(),)


@lru_cache(maxsize=2048)
def get_compatible_genres(genre_str):
    """
    Retorna o set de géneros compatíveis para um dado género.
    Trata géneros compostos (House/Pop) — combina a compatibilidade de cada parte.

    OPT: chamada por candidato nos loops quentes do motor de playlists e do
    filtro de pesquisa, com substring-matching sobre todo o GENRE_COMPATIBILITY.
    É função pura de string → cacheada. Retorna frozenset (imutável) para a
    cache ser segura; todos os callers apenas iteram/testam pertença.
    """
    parts = split_genres(genre_str)
    all_compatible = set()
    for part in parts:
        if part in GENRE_COMPATIBILITY:
            all_compatible.update(GENRE_COMPATIBILITY[part])
            continue
        found = False
        for key, compat_set in GENRE_COMPATIBILITY.items():
            if key in part or part in key:
                all_compatible.update(compat_set)
                found = True
                break
        if not found:
            all_compatible.add(part)
    return frozenset(all_compatible)


def genre_matches_filter(track_genre_str, filter_genre_str, strict=False):
    """
    Verifica se o género de uma faixa corresponde ao filtro de género da pesquisa.

    strict=True  (caixa de pesquisa): só o género pedido, aliases e subgéneros.
                 "disco" casa Disco / Nu-Disco / Disco House — NÃO House/Pop
                 nem Afro House só porque o grafo de compatibilidade os mistura.
    strict=False (Set Planner / Harmónico): inclui géneros compatíveis, como
                 sempre, para o motor de playlists poder cruzar vizinhos.
    """
    filter_norm = normalize_genre(filter_genre_str)
    filter_cmp = re.sub(r'[-_]+', ' ', filter_norm)
    track_parts = split_genres(track_genre_str)

    # 1. Match exacto (alguma parte do track_genre é igual ao filtro)
    if filter_norm in track_parts:
        return True
    for part in track_parts:
        part_cmp = re.sub(r'[-_]+', ' ', part)
        if filter_cmp == part_cmp:
            return True
        # Subgénero: "disco" ⊂ "disco house" / "nu disco"; "house" ⊂ "afro house"
        if len(filter_cmp) >= 4 and (filter_cmp in part_cmp or part_cmp in filter_cmp):
            return True

    # 2. Substring no campo completo (hyphens já normalizados)
    track_cmp = re.sub(r'[-_/|;,&]+', ' ', track_genre_str.lower())
    if len(filter_cmp) >= 4 and filter_cmp in track_cmp:
        return True

    if strict:
        return False

    # 3. Compatibilidade (só playlists — NÃO a caixa de pesquisa)
    filter_compatible = get_compatible_genres(filter_genre_str)
    for part in track_parts:
        if part in filter_compatible:
            return True
        for comp_g in filter_compatible:
            if comp_g in part or part in comp_g:
                return True

    return False


def is_known_genre_term(term):
    """
    Verifica se um termo de pesquisa corresponde a um género musical conhecido.
    Usado para decidir se texto livre deve ser interpretado como filtro de género.
    """
    t = term.lower().strip()
    # Match directo
    if t in _ALL_KNOWN_GENRES:
        return True
    # Match parcial: o termo é uma parte significativa de um género conhecido
    if len(t) >= 3:
        for known in _ALL_KNOWN_GENRES:
            if t == known or (len(t) >= 4 and (t in known or known in t)):
                return True
    return False


@lru_cache(maxsize=4096)
def genre_score(ref_g, cand_g):
    """
    Retorna um score de penalidade por género (0.0 = mesmo género, 1.0 = incompatível).
    Trata géneros compostos em ambos os lados.

    OPT: função pura (str, str) → float, chamada uma vez por candidato em
    reference_similarity, na pré-extração vectorizada do motor v2 e no
    set-planner. Numa biblioteca real os pares (ref, cand) repetem-se em cada
    regeneração — a cache elimina o custo quase por completo.
    """
    ref_parts = set(split_genres(ref_g))
    cand_parts = set(split_genres(cand_g))

    # Match exacto (pelo menos uma parte em comum)
    if ref_parts & cand_parts:
        return 0.0

    # Verificar compatibilidade
    compatible = get_compatible_genres(ref_g)
    for cand_part in cand_parts:
        if cand_part in compatible:
            return 0.15
        for comp_g in compatible:
            if comp_g in cand_part or cand_part in comp_g:
                return 0.25

    return 1.0  # Género incompatível — penalidade total

# ----------------------------------------------------------------------
# Funções de pesquisa partilhadas (usadas em MusicListWidget e DatabaseManagerWidget)
# ----------------------------------------------------------------------
def parse_search_query(search_text):
    """Parse advanced search query into structured filters.
    Supports: bpm:120, bpm:118-122, key:8B, camelot:5A, genre:house, energy:0.5-0.8, cluster:3
    Free text (without prefix) searches by filename AND auto-detects genre terms.
    """
    filters = {'name_parts': [], 'genre_terms': []}
    tokens = search_text.strip().split()

    for token in tokens:
        token_lower = token.lower()

        if ':' in token_lower:
            prefix, value = token_lower.split(':', 1)
            if not value:
                continue

            if prefix == 'bpm':
                if '-' in value:
                    parts = value.split('-', 1)
                    try:
                        filters['bpm_min'] = float(parts[0])
                        filters['bpm_max'] = float(parts[1])
                    except ValueError:
                        filters['name_parts'].append(token)
                else:
                    try:
                        bpm_val = float(value)
                        filters['bpm_min'] = bpm_val - 2.0
                        filters['bpm_max'] = bpm_val + 2.0
                    except ValueError:
                        filters['name_parts'].append(token)

            elif prefix in ('key', 'camelot'):
                filters['camelot'] = value.upper()

            elif prefix in ('genre', 'genero', 'género'):
                filters['genre'] = value

            elif prefix in ('energy', 'energia'):
                if '-' in value:
                    parts = value.split('-', 1)
                    try:
                        filters['energy_min'] = float(parts[0])
                        filters['energy_max'] = float(parts[1])
                    except ValueError:
                        filters['name_parts'].append(token)
                else:
                    try:
                        e_val = float(value)
                        filters['energy_min'] = max(0.0, e_val - 0.05)
                        filters['energy_max'] = min(1.0, e_val + 0.05)
                    except ValueError:
                        filters['name_parts'].append(token)

            elif prefix == 'cluster':
                try:
                    filters['cluster'] = int(value)
                except ValueError:
                    filters['name_parts'].append(token)
            else:
                filters['name_parts'].append(token)
        else:
            # Texto livre: verificar se é um género musical conhecido
            if is_known_genre_term(token_lower):
                filters['genre_terms'].append(token_lower)
            else:
                filters['name_parts'].append(token)

    return filters


def track_matches_filters(path, music_info, filters):
    """Check if a track matches all active filters.

    Free-text genre terms (e.g. "disco") and genre: prefixes are STRICT:
    the track's own genre / subgenre, or the filename — never the
    compatibility graph used by the set planner.
    """
    basename_lower = os.path.basename(path).lower()

    # Name filter (all name parts must match filename OR genre field)
    if filters['name_parts']:
        track_genre_lower = music_info.get('genre', '').lower()
        for part in filters['name_parts']:
            part_lower = part.lower()
            if part_lower not in basename_lower and part_lower not in track_genre_lower:
                return False

    # Genre terms auto-detected from free text (e.g., user typed "disco")
    if filters.get('genre_terms'):
        track_genre = music_info.get('genre', 'Unknown')
        for genre_term in filters['genre_terms']:
            name_hit = genre_term in basename_lower
            genre_hit = genre_matches_filter(track_genre, genre_term, strict=True)
            if not name_hit and not genre_hit:
                return False

    # Explicit genre: prefix (e.g., genre:disco) — also strict
    if 'genre' in filters:
        track_genre = music_info.get('genre', 'Unknown')
        if not genre_matches_filter(track_genre, filters['genre'], strict=True):
            return False

    # BPM filter
    if 'bpm_min' in filters or 'bpm_max' in filters:
        bpm = music_info.get('bpm', 0.0)
        if not isinstance(bpm, (int, float)):
            return False
        bpm_min = filters.get('bpm_min', 0.0)
        bpm_max = filters.get('bpm_max', 999.0)
        matches_bpm = False
        for ratio in [0.5, 1.0, 2.0]:
            adjusted_bpm = bpm * ratio
            if bpm_min <= adjusted_bpm <= bpm_max:
                matches_bpm = True
                break
        if not matches_bpm:
            return False

    # Camelot/Key filter
    if 'camelot' in filters:
        track_camelot = music_info.get('camelot', 'N/A').upper()
        filter_camelot = filters['camelot']
        if track_camelot == 'N/A':
            return False
        if track_camelot != filter_camelot:
            try:
                filter_num = int(re.sub(r'[AB]', '', filter_camelot))
                filter_letter = re.sub(r'[0-9]', '', filter_camelot)
                track_num = int(re.sub(r'[AB]', '', track_camelot))
                track_letter = re.sub(r'[0-9]', '', track_camelot)
                compatible = False
                if track_num == filter_num and track_letter != filter_letter:
                    compatible = True
                elif track_letter == filter_letter and abs(track_num - filter_num) == 1:
                    compatible = True
                elif track_letter == filter_letter and {track_num, filter_num} == {1, 12}:
                    compatible = True
                if not compatible:
                    return False
            except (ValueError, IndexError):
                return False

    # Energy filter
    if 'energy_min' in filters or 'energy_max' in filters:
        energy = music_info.get('energy', 0.5)
        if not isinstance(energy, (int, float)):
            return False
        if energy < filters.get('energy_min', 0.0) or energy > filters.get('energy_max', 1.0):
            return False

    # Cluster filter
    if 'cluster' in filters:
        track_cluster = music_info.get('cluster', -1)
        try:
            if int(track_cluster) != filters['cluster']:
                return False
        except (ValueError, TypeError):
            return False

    return True


