        def make_action_btn(key, accent=False):
            btn = QPushButton("")
            self.translatable_widgets[key] = btn
            if accent:
                btn.setStyleSheet("""
                    QPushButton {
                        background-color: #00BCD4; color: #06222a; font-weight: bold;
                        border: 1px solid #00BCD4; border-radius: 8px;
                        padding: 12px; font-size: 14px; min-width: 80px;
                    }
                    QPushButton:hover { background-color: #00E5FF; border-color: #00E5FF; }
                    QPushButton:pressed { background-color: #0097A7; }
                    QPushButton:disabled { background-color: #1b1e23; color: #6b7079; border-color: #262b32; }
                """)
            else:
                btn.setStyleSheet("""
                    QPushButton {
                        background-color: #232830; color: #e8eaed;
                        border: 1px solid #333a44; border-radius: 8px;
                        padding: 12px; font-size: 14px; min-width: 80px;
                    }
                    QPushButton:hover { background-color: #2c333d; border-color: #00BCD4; }
                    QPushButton:pressed { background-color: #0097A7; color: #06222a; }
                    QPushButton:disabled { background-color: #1b1e23; color: #6b7079; border-color: #262b32; }
                """)
            btn.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
            bottom_h.addWidget(btn)
            return btn

